Here’s a complete example using HTML, JavaScript, and the DOM to add, complete, and delete tasks:

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <title>To-Do List</title>
  <style>
    .done { text-decoration: line-through; color: gray; }
    li { margin: 8px 0; }
    button { margin-left: 8px; }
  </style>
</head>
<body>
  <h1>To-Do List</h1>

  <input id="taskInput" placeholder="Enter a task" />
  <button id="addButton">Add</button>

  <ul id="taskList"></ul>

  <script>
    const input = document.querySelector("#taskInput");
    const addButton = document.querySelector("#addButton");
    const taskList = document.querySelector("#taskList");

    function addTask() {
      const text = input.value.trim();
      if (!text) return;

      const li = document.createElement("li");
      li.textContent = text;

      li.addEventListener("click", () => {
        li.classList.toggle("done");
      });

      const deleteButton = document.createElement("button");
      deleteButton.textContent = "Delete";
      deleteButton.addEventListener("click", (event) => {
        event.stopPropagation();
        li.remove();
      });

      li.appendChild(deleteButton);
      taskList.appendChild(li);
      input.value = "";
      input.focus();
    }

    addButton.addEventListener("click", addTask);
    input.addEventListener("keydown", (event) => {
      if (event.key === "Enter") addTask();
    });
  </script>
</body>
</html>
```

Clicking a task toggles its completed style, while the **Delete** button removes it from the DOM.

```python
def fibonacci(n: int) -> int:
    """Return the nth Fibonacci number, with F(0)=0 and F(1)=1."""
    if n < 0:
        raise ValueError("n must be non-negative")

    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a
```

```python
def is_prime(n: int) -> bool:
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False

    divisor = 3
    while divisor * divisor <= n:
        if n % divisor == 0:
            return False
        divisor += 2
    return True
```

The function tests divisors only up to \(\sqrt{n}\), so its time complexity is \(O(\sqrt{n})\) and its space complexity is \(O(1)\).
